export function paintLaundryRoutes(c,images,age,input={}){const f={...routeDefaults,...input},routes=f.laundryRoutes||defaultRoutes,im=images.precisionLinen;if(!im?.naturalWidth)return;for(const [index,route] of routes.entries()){const state=routeState(route,age*f.laundryRouteSpeed,{startSize:f.laundryRouteStartSize,endSize:f.laundryRouteEndSize});if(!state.visible)continue;paintRouteLine(c,route.points,state.q,{color:f.laundryRouteColor,thickness:f.laundryRouteWidth,style:f.laundryRouteStyle,dash:f.laundryRouteDash,gap:f.laundryRouteGap,opacity:f.laundryRouteOpacity});const media=images[route.slot]||im,w=state.width,h=w*media.naturalHeight/media.naturalWidth;c.save();c.globalAlpha*=(f.laundryGarmentOpacity??1)*(index===0&&!route.delay?1:state.opacity);c.translate(state.point[0]*960,state.point[1]*540);c.rotate((route.rotation||0)*Math.PI/180);drawAssetMedia(c,media,[-w/2,-h/2,w,h],f,age);c.restore()}}
